import { composeValue } from './composeValue.js';
import type { ComposePlan } from './composePlan.js';
import type { Stack } from './stackPorts.js';

/**
 * Serialise the plan as compose YAML. Hand-rolled because the shape is small, fixed and fully ours.
 *
 * @param plan - The compose plan.
 * @param localStack - The stack: it names the project and every container.
 * @returns The file's text. Pure.
 */
export function composeYaml(plan: ComposePlan, localStack: Stack): string {
    const lines = [
        '# GENERATED by `npm run local:up` from the synthesised CDK. Do not edit — regenerate.',
        '',
        `name: ${localStack.project}`,
        '',
        'services:',
    ];

    for (const [name, service] of Object.entries(plan.services)) {
        if (service === undefined) {
            continue;
        }

        lines.push(
            `    ${name}:`,
            `        image: ${service.image}`,
            `        container_name: ${localStack.containerName(name)}`,
            '        restart: unless-stopped',
            // A service in another's network namespace may not publish ports.
            ...(service.networkMode === undefined ? [] : [`        network_mode: ${service.networkMode}`]),
            ...(service.command === undefined ? [] : [`        command: ${JSON.stringify(service.command)}`]),
            ...(service.ports.length === 0
                ? []
                : ['        ports:', ...service.ports.map((port) => `            - '${port}'`)]),
            '        environment:',
            ...Object.entries(service.environment).map(([key, value]) => `            ${key}: ${composeValue(value)}`),
            '        healthcheck:',
            `            test: ${JSON.stringify(service.healthcheck.test)}`,
            `            interval: ${service.healthcheck.interval}`,
            `            timeout: ${service.healthcheck.timeout}`,
            `            retries: ${String(service.healthcheck.retries)}`,
        );

        if (service.dependsOn !== undefined) {
            lines.push(
                '        depends_on:',
                ...service.dependsOn.flatMap((dep) => [
                    `            ${dep}:`,
                    '                condition: service_healthy',
                ]),
            );
        }

        if (service.volumes !== undefined) {
            lines.push('        volumes:', ...service.volumes.map((volume) => `            - ${volume}`));
        }

        if (name === 'postgres') {
            lines.push('            - ./init.sql:/docker-entrypoint-initdb.d/init.sql:ro');
        }
    }

    lines.push('', 'volumes:', '    local-sandbox-pgdata:', '');

    return lines.join('\n');
}
